def measure_erosion(
    functions: tuple[FunctionEvidence, ...], scope: MetricScope, threshold: int
) -> MetricResult:
    """Measure the fraction of mass above a strict complexity threshold."""
    if isinstance(threshold, bool) or not isinstance(threshold, int) or threshold <= 0:
        raise ValueError("complexity threshold must be a positive integer")
    if isinstance(scope, FileMetricScope) and any(
        function.path != scope.path for function in functions
    ):
        raise ValueError("function path must match the file metric scope")
    if not functions:
        return UnavailableMetric(
            metric_id="m4.erosion", scope=scope, reason=UnavailableReason.NO_FUNCTIONS
        )
    total = fsum(function.mass for function in functions)
    eroded = fsum(
        function.mass for function in functions if function.cyclomatic_complexity > threshold
    )
    return MeasuredMetric(
        metric_id="m4.erosion",
        scope=scope,
        raw=MetricMeasurement(
            numerator=eroded, denominator=total, value=eroded / total, unit=MetricUnit.RATIO
        ),
    )

def _normalized_extensions(extensions: frozenset[str]) -> frozenset[str]:
    if not extensions:
        raise ValueError("an adapter must declare at least one extension")
    normalized: set[str] = set()
    for extension in extensions:
        if (
            not isinstance(extension, str)
            or not extension.startswith(".")
            or extension == "."
            or "/" in extension
            or "\\" in extension
            or "." in extension[1:]
            or "\0" in extension
            or any(character.isspace() for character in extension)
        ):
            raise ValueError(
                "an extension must be one dot-prefixed suffix without whitespace, NUL, "
                "or path separators"
            )
        key = extension.casefold()
        if key in normalized:
            raise ValueError(f"duplicate extension: {extension}")
        normalized.add(key)
    return frozenset(normalized)

def _contained(inner: CloneGroup, outer: CloneGroup) -> bool:
    if (
        inner.language != outer.language
        or inner.cohort is not outer.cohort
        or inner.normalization_version != outer.normalization_version
        or len(inner.members) > len(outer.members)
        or _size(inner) >= _size(outer)
    ):
        return False
    by_path: dict[str, list[tuple[int, CloneMember]]] = {}
    for index, member in enumerate(outer.members):
        by_path.setdefault(member.path.root, []).append((index, member))
    choices = tuple(
        tuple(
            index for index, member in by_path.get(child.path.root, ()) if _encloses(member, child)
        )
        for child in inner.members
    )
    assigned: dict[int, int] = {}

    def assign(child: int, visited: set[int]) -> bool:
        for parent in choices[child]:
            if parent in visited:
                continue
            visited.add(parent)
            previous = assigned.get(parent)
            if previous is None or assign(previous, visited):
                assigned[parent] = child
                return True
        return False

    return all(assign(index, set()) for index in range(len(inner.members)))

def _scan(self, request: SnapshotRequest) -> _Snapshot:
    config = request.config.model_copy(
        update={"languages": self.registry.resolve_languages(request.config.languages)}
    )
    adapters = (
        tuple(self.registry.get(language) for language in sorted(config.languages))
        if config.languages
        else self.registry.adapters
    )
    for adapter in adapters:
        validate_config = getattr(adapter, "validate_config", None)
        if validate_config is not None:
            validate_config(config)
    provider = (
        FilesystemSourceProvider(request.target.root, config, self.registry)
        if isinstance(request.target, DirectorySourceReference)
        else GitSourceProvider(
            request.target.root, request.target.revision, config, self.registry
        )
    )
    inventory = provider.inventory()
    evidence: list[LanguageEvidence] = []
    versions: list[AnalyzerVersion] = []
    for adapter in adapters:
        documents = tuple(
            doc for doc in inventory.documents if doc.language == adapter.language_id
        )
        try:
            result = adapter.analyze(documents, config)
            _validate_evidence(adapter, documents, result)
        except Exception:
            result = _failed_adapter(adapter.language_id, documents)
        evidence.append(result)
        versions.append(
            AnalyzerVersion(
                language=adapter.language_id,
                adapter_version=getattr(adapter, "adapter_version", "unversioned"),
                rule_set_version=getattr(adapter, "rule_set_version", None),
                clone_normalization_version=getattr(
                    adapter, "clone_normalization_version", None
                ),
            )
        )
    report = aggregate_snapshot(
        provider.identity(),
        inventory,
        tuple(evidence),
        config,
        analyzers=tuple(versions),
    )
    failures = [
        item.detail
        for item in report.diagnostics
        if item.detail.severity is DiagnosticSeverity.ERROR
    ]
    if request.config.strict and failures:
        first = failures[0]
        location = f"{first.path.root}: " if first.path else ""
        raise AnalysisFailure(f"Strict analysis failed: {location}{first.message}")
    return _Snapshot(report, inventory)

def aggregate_snapshot(
    identity: SourceIdentity,
    inventory: SourceInventory,
    evidence: tuple[LanguageEvidence, ...],
    config: AnalysisConfig,
    *,
    analyzers: tuple[AnalyzerVersion, ...] = (),
) -> AnalysisReport:
    """Aggregate source coverage and raw metrics without averaging file ratios."""
    diagnostics = _diagnostics(
        inventory.diagnostics
        + tuple(item for language in evidence for item in language.diagnostics)
        + tuple(
            analysis.diagnostic
            for language in evidence
            for analysis in language.function_analyses
            if isinstance(analysis, FailedFunctions)
        )
        + tuple(
            analysis.diagnostic
            for language in evidence
            for analysis in language.pattern_analyses
            if isinstance(analysis, FailedPatterns)
        )
        + tuple(
            outcome.diagnostic
            for language in evidence
            for outcome in language.clone_analyses
            if isinstance(outcome, FailedClones)
        )
    )
    files = tuple(
        sorted(
            inventory.failed_files
            + tuple(file for language in evidence for file in language.files),
            key=lambda file: file.path.root,
        )
    )
    groups = group_clones(
        files, tuple(candidate for language in evidence for candidate in language.clone_candidates)
    )
    languages = sorted(
        {item.language for item in evidence}
        | {item.language for item in analyzers}
        | {file.language for file in files}
    )
    cohorts: list[SnapshotCohortReport] = []
    coverage = [ReportCoverage(detail=item) for item in inventory.coverage]
    for language in languages:
        project_errors = _project_errors(language, inventory, evidence, diagnostics)
        metrics = _snapshot_metrics(language, evidence, diagnostics, config, groups)
        for cohort in Cohort:
            members = tuple(
                file for file in files if file.language == language and file.cohort is cohort
            )
            cohorts.append(
                SnapshotCohortReport(
                    language=language,
                    cohort=cohort,
                    current=_cohort_result(members, cohort, diagnostics, project_errors, metrics),
                )
            )
            coverage.append(
                ReportCoverage(
                    detail=Coverage(
                        state=CoverageState.SCORED,
                        cohort=cohort,
                        language=language,
                        file_count=len(members),
                        sloc=sum(file.sloc for file in members),
                    )
                )
            )
    return AnalysisReport(
        analysis=SnapshotAnalysis(current=identity),
        provenance=Provenance(
            tool_version=__version__,
            config=config,
            analyzers=tuple(sorted(analyzers, key=lambda item: item.language)),
            metrics=_versions(evidence),
        ),
        cohorts=tuple(cohorts),
        coverage=tuple(sorted(coverage, key=_coverage_key)),
        excluded_directories=tuple(
            ReportExcludedDirectory(detail=item) for item in inventory.excluded_directories
        ),
        diagnostics=diagnostics,
        findings=_findings(evidence),
        clone_groups=tuple(
            ReportCloneGroup(
                id="clone-" + sha256(group.model_dump_json().encode()).hexdigest()[:20],
                detail=group,
            )
            for group in groups
        ),
    )
